import {
  pgTable,
  uuid,
  text,
  real,
  integer,
  timestamp,
} from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";

/**
 * Task 3: problem_statements
 * Stores synthesized problem statements generated by the agent pipeline
 */
export const problemStatements = pgTable("problem_statements", {
  id: uuid("id").primaryKey().default(sql`gen_random_uuid()`),
  title: text("title").notNull(),
  statementText: text("statement_text").notNull(),
  category: text("category"),
  // draft | pending_review | live | assigned | in_progress | solved | rejected
  status: text("status").notNull().default("draft"),
  confidence: real("confidence"),
  evidenceCount: integer("evidence_count").notNull().default(0),
  affectedArea: text("affected_area"),
  solutionDomain: text("solution_domain"),
  targetInstitutionType: text("target_institution_type"),
  version: integer("version").notNull().default(1),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

export type ProblemStatement = typeof problemStatements.$inferSelect;
export type NewProblemStatement = typeof problemStatements.$inferInsert;
